local function round(num)
	return math.round(num*10000)/10000
end

-- Function to serialize an instance and its children
local function serializeInstance(instance)
	local data = {
		Name = instance.Name,
		ClassName = instance.ClassName,
		Properties = {},
		Children = {}
	}

	-- Get the list of properties for this class
	for className, properties in pairs(propertyMap) do
		if instance:IsA(className) then
			for _, property in ipairs(properties) do
				local success, value = pcall(function()
					return instance[property]
				end)
				if success then
					-- Handle special cases like enums or complex types
					if typeof(value) == "number" then
						value = round(value)
					elseif typeof(value) == "EnumItem" then
						value = value.Name
					elseif typeof(value) == "Color3" then
						value = { R = round(value.R), G = round(value.G), B = round(value.B) }
					elseif typeof(value) == "Vector3" then
						value = { X = round(value.X), Y = round(value.Y), Z = round(value.Z) }
					elseif typeof(value) == "CFrame" then
						value = { value:GetComponents() }
					elseif typeof(value) == "ColorSequence" then
						value = { Keypoints = value.Keypoints }
					elseif typeof(value) == "NumberSequence" then
						value = { Keypoints = value.Keypoints }
					elseif typeof(value) == "NumberRange" then
						value = { Min = round(value.Min), Max = round(value.Max) }
					elseif typeof(value) == "UDim2" then
						value = { 
							X = {Scale = round(value.X.Scale), Offset = round(value.X.Offset)},
							Y = {Scale = round(value.Y.Scale), Offset = round(value.Y.Offset)}
						}
					end
					data.Properties[property] = value
				end
			end
		end
	end

	-- Serialize children recursively
	for _, child in ipairs(instance:GetChildren()) do
		-- make sure the children is a valid class
		for className, properties in pairs(propertyMap) do
			if instance:IsA(className) then
				table.insert(data.Children, serializeInstance(child))
				break
			end
		end
	end

	return data
end



-- Serialize all selected instances
local serializedData = {}
for _,ROOT in pairs(ROOTS) do
	for _,instance in pairs(ROOT:GetChildren()) do
		-- make sure the children is a valid class
		for className, properties in pairs(propertyMap) do
			if instance:IsA(className) then
				table.insert(serializedData, serializeInstance(instance))
			end
		end
	end
end

-- Convert to JSON
local HttpService = game:GetService("HttpService")
local jsonData = HttpService:JSONEncode(serializedData)


