function box(num, txt)
	local txtbox = Instance.new('TextBox')
	txtbox.Name = "DEX_TXTBOX_" .. num
	-- size already determined by the grid layout
	txtbox.BackgroundColor3 = Color3.new(1,1,1)
	txtbox.TextSize = 12
	txtbox.ClearTextOnFocus = false
	txtbox.TextWrapped = true
	txtbox.Text = txt
	txtbox.Parent = SCROLL

	local pagenum = Instance.new('TextLabel')
	pagenum.BackgroundColor3 = Color3.new(0,0,0)
	pagenum.BackgroundTransparency = 0.5
	pagenum.TextScaled = true
	pagenum.TextColor3 = Color3.new(1,1,1)
	pagenum.TextStrokeTransparency = 0
	pagenum.Size = UDim2.new(0,25,0,25)
	pagenum.Position = UDim2.new(0,0,1,-25)
	pagenum.Text = num
	pagenum.Parent = txtbox
end

function split(inputString, chunkLength)
	local result = {}
	local length = #inputString

	for i = 1, length, chunkLength do
		local chunk = inputString:sub(i, i + chunkLength - 1)
		table.insert(result, chunk)
	end

	return result
end


local pages = split(jsonData, 2^14-1024)
for num,data in pairs(pages) do
	box(num,data)
